update public.spell_catalog set name_ru='Возвращение к жизни', casting_time='Действие', spell_range='Касание', area='1 существо, умершее не более 1 минуты назад', duration='Мгновенно', components=array['В','С','М'], material='алмазы стоимостью 300+ зм, расходуются', check_type='', damage='Возвращает с 1 HP', effect_summary='Касаешься существа, умершего не более минуты назад, и возвращаешь его к жизни с 1 HP.', upcast='', notes='Материал расходуется. Не возвращает умершего от старости и не восстанавливает утраченные части тела.', author_description='Триста золотых, одна минута и очень убедительная попытка спорить со смертью. Жрецы называют это чудом. Торговцы алмазами — стабильным рынком.', author_comment='Смерть окончательна. Кроме случаев, когда у друзей есть деньги и секундомер.' where slug='revivify';
update public.spell_catalog set name_ru='Послание', casting_time='Действие', spell_range='Неограниченная', area='1 знакомое или достаточно описанное существо', duration='Мгновенно', components=array['В','С','М'], material='медная проволока', check_type='Другой план: 5% шанс сбоя доставки', damage='', effect_summary='Отправляешь мысленное сообщение до 25 слов существу, которого встречал, либо которое тебе описал тот, кто его встречал. Цель понимает смысл и может сразу ответить таким же образом. Работает на любом расстоянии и между планами.', upcast='', notes='Если цель на другом плане, есть 5% шанс, что сообщение не дойдёт; ты узнаёшь о сбое. Получатель может заблокировать твои следующие Послания на 8 часов.', author_description='Двадцать пять слов через любое расстояние и даже между мирами. Человечество изобрело межпланарную связь и всё равно первым делом получило возможность заблокировать отправителя.', author_comment='Если тебя заблокировали магией на восемь часов, возможно, проблема не в качестве связи.' where slug='sending';
update public.spell_catalog set name_ru='Ледяная буря', casting_time='Действие', spell_range='150 футов', area='Цилиндр радиусом 20 и высотой 40 футов', duration='Концентрация, до 1 минуты', components=array['В','С','М'], material='миниатюрный зонтик', check_type='Спасбросок Ловкости при первом входе за ход или начале хода', damage='', effect_summary='В цилиндре идёт ледяной дождь. Область сильно заслонена, открытое пламя гаснет, земля становится труднопроходимой. Существо при первом входе за ход или начале хода делает спасбросок Ловкости; при провале падает Сбитым с ног и теряет Концентрацию.', upcast='', notes='Провал спасброска автоматически прекращает поддерживаемую целью Концентрацию.', author_description='Дождь, лёд, плохая видимость и гарантированный шанс кого-нибудь уронить. Друид наконец научился создавать погоду, которую обычно обещают бесплатно.', author_comment='Лучшее средство против вражеской концентрации — превратить поле боя в скользкую парковку.' where slug='sleet-storm';
update public.spell_catalog set name_ru='Замедление', casting_time='Действие', spell_range='120 футов', area='До 6 выбранных существ в кубе 40 футов', duration='Концентрация, до 1 минуты', components=array['В','С','М'], material='капля патоки', check_type='Спасбросок Мудрости; повтор в конце каждого хода', damage='', effect_summary='При провале скорость цели уменьшается вдвое, КД и спасброски Ловкости получают −2, Реакции недоступны. В свой ход цель выбирает либо Действие, либо Бонусное действие, но не оба, и при действии Атака делает только одну атаку. Заклинание с соматическим компонентом имеет 25% шанс провалиться.', upcast='', notes='Цель повторяет спасбросок в конце каждого своего хода и прекращает эффект при успехе.', author_description='Делаешь до шести существ медленными, неуклюжими и раздражёнными. Магия наконец моделирует утро после трёхдневного похода.', author_comment='Если вражеский маг с шансом 25% забывает вовремя пошевелить руками, это уже почти честная драка.' where slug='slow';
update public.spell_catalog set name_ru='Разговор с мёртвыми', casting_time='Действие', spell_range='10 футов', area='1 труп с ртом', duration='10 минут', components=array['В','С','М'], material='горящий ладан', check_type='', damage='', effect_summary='На 10 минут даёшь трупу подобие жизни и можешь задать до пяти вопросов. Он знает только то, что знал при жизни, отвечает обычно кратко, туманно или повторяясь и не обязан быть правдивым, если относился к тебе враждебно.', upcast='', notes='Не работает, если умерший был Нежитью в момент смерти или этот труп уже был целью заклинания за последние 10 дней. Душа не возвращается; труп не узнаёт новых сведений и не предсказывает будущее.', author_description='Пять вопросов человеку, который уже умер и всё равно не обязан говорить правду. Наконец собеседник, чьи социальные навыки соответствуют средней группе приключенцев.', author_comment='Смерть не делает людей честнее. Зато обычно делает их заметно терпеливее.' where slug='speak-with-dead';
update public.spell_catalog set name_ru='Разговор с растениями', casting_time='Действие', spell_range='На себя', area='Неподвижная эманация радиусом 30 футов', duration='10 минут', components=array['В','С'], material=null, check_type='', damage='', effect_summary='Растения в неподвижной области получают ограниченную разумность, могут общаться и выполнять простые команды. Их можно расспросить о событиях здесь за последние сутки. Растительную труднопроходимую местность можно временно сделать обычной или наоборот. С существом типа Растение можно общаться как при общем языке.', upcast='', notes='Область не движется вместе с тобой. Растения не могут выкорчеваться и ходить, но могут двигать ветвями, стеблями и усиками.', author_description='На десять минут местная растительность становится достаточно разумной, чтобы отвечать на вопросы, вспоминать прохожих и жалеть о том, что получила сознание именно рядом с вами.', author_comment='Наконец-то хотя бы один собеседник не сможет от тебя убежать. Правда, если даже куст через десять минут перестал отвечать — возможно, проблема всё-таки не в собеседниках.' where slug='speak-with-plants';
update public.spell_catalog set name_ru='Духовные стражи', casting_time='Действие', spell_range='На себя', area='Эманация радиусом 15 футов', duration='Концентрация, до 10 минут', components=array['В','С','М'], material='молитвенный свиток', check_type='Спасбросок Мудрости; не чаще 1 раза за ход на существо', damage='3к8 излучением для доброго/нейтрального заклинателя или 3к8 некротического для злого; половина при успехе', effect_summary='Вокруг тебя появляются защитные духи. При наложении можно назначить существ, которых они игнорируют. Скорость остальных существ в эманации уменьшается вдвое. Когда эманация входит в пространство существа, либо оно входит или заканчивает там ход, оно делает спасбросок.', upcast='+1к8 урона за каждый уровень ячейки выше 3.', notes='Одно существо делает спасбросок не чаще одного раза за ход. Вид духов зависит от мировоззрения заклинателя.', author_description='Жрец окружает себя толпой духов, которые замедляют и режут всех неподходящих посетителей. Похоже, даже загробная жизнь не смогла придумать способ заставить жреца стоять впереди в одиночку.', author_comment='Когда вокруг жреца летают пятнадцать футов вооружённой веры, спор о религии лучше отложить.' where slug='spirit-guardians';
update public.spell_catalog set name_ru='Зловонное облако', casting_time='Действие', spell_range='90 футов', area='Сфера радиусом 20 футов', duration='Концентрация, до 1 минуты', components=array['В','С','М'], material='тухлое яйцо', check_type='Спасбросок Телосложения в начале хода', damage='', effect_summary='Создаёшь сферу тошнотворного жёлтого газа, которая сильно заслоняет область. Существо, начинающее ход внутри, при провале становится Отравленным до конца текущего хода; пока Отравлено этим способом, не может совершать Действия или Бонусные действия.', upcast='', notes='Сильный ветер рассеивает облако.', author_description='Двадцать футов газа из тухлого яйца, который лишает людей желания и возможности что-либо делать. Некоторые трактиры предоставляют похожий эффект бесплатно.', author_comment='Если враг не может действовать от запаха, технически это всё ещё контроль поля боя.' where slug='stinking-cloud';
update public.spell_catalog set name_ru='Маленькая хижина', casting_time='Действие', spell_range='На себя', area='Неподвижная эманация радиусом 10 футов', duration='8 часов', components=array['В','С','М'], material='хрустальная бусина', check_type='', damage='', effect_summary='Вокруг тебя появляется неподвижное защищённое убежище. Существа и предметы, находившиеся внутри при наложении, могут проходить свободно; остальные не могут войти. Заклинания 3 уровня и ниже нельзя проводить сквозь границу, и их эффекты не распространяются внутрь. Внутри сухо и комфортно.', upcast='', notes='Ритуал. Снаружи оболочка непрозрачна, изнутри прозрачна. Можно менять внутреннее освещение между тусклым светом и тьмой. Заканчивается раньше, если ты покидаешь область или накладываешь его снова.', author_description='Восемь часов сухости, безопасности и права не разговаривать с внешним миром. Волшебники наконец создали магию, которой я искренне завидую.', author_comment='Если вся партия помещается внутрь и молчит — это уже почти роскошный отдых.' where slug='tiny-hut';
update public.spell_catalog set name_ru='Языки', casting_time='Действие', spell_range='Касание', area='1 существо', duration='1 час', components=array['В','М'], material='миниатюрный зиккурат', check_type='', damage='', effect_summary='Цель понимает любой услышанный разговорный язык и любой увиденный язык жестов. Когда сама говорит или жестикулирует, её понимает любое существо, знающее хотя бы один язык и способное услышать или увидеть сообщение.', upcast='', notes='Не требует концентрации.', author_description='На час устраняет языковой барьер. К сожалению, заклинание не добавляет человеку ничего умного для разговора.', author_comment='Теперь тебя понимают все. Это не обязательно улучшает ситуацию.' where slug='tongues';
update public.spell_catalog set name_ru='Вампирическое касание', casting_time='Действие', spell_range='На себя', area='Существо в пределах досягаемости', duration='Концентрация, до 1 минуты', components=array['В','С'], material=null, check_type='Рукопашная атака заклинанием', damage='3к6 некротического урона; лечишься на половину реально нанесённого некротического урона', effect_summary='Совершая рукопашную атаку заклинанием, вытягиваешь жизненную силу из цели. При попадании наносишь 3к6 некротического урона и восстанавливаешь HP в размере половины нанесённого некротического урона. Пока длится заклинание, можешь повторять атаку действием Магии каждый ход.', upcast='+1к6 урона за каждый уровень ячейки выше 3.', notes='Лечение зависит от фактически нанесённого некротического урона.', author_description='Бьёшь человека магией и используешь его здоровье как своё. Некромантия называет это обменом жизненной силой. Жертва почему-то не считает обмен добровольным.', author_comment='Если после рукопожатия ты чувствуешь себя хуже, а волшебник лучше — этикет снова подвёл.' where slug='vampiric-touch';
update public.spell_catalog set name_ru='Дыхание под водой', casting_time='Действие', spell_range='30 футов', area='До 10 добровольных существ', duration='24 часа', components=array['В','С','М'], material='короткая тростинка', check_type='', damage='', effect_summary='До десяти добровольных существ могут дышать под водой 24 часа, сохраняя и обычный способ дыхания.', upcast='', notes='Ритуал. Не требует концентрации.', author_description='Десять человек сутки дышат под водой. Следопыт назовёт это подготовкой. Волшебник — поводом немедленно искать затонувшие руины.', author_comment='Умение дышать под водой не означает умение плавать. Это уточнение существует по печальным причинам.' where slug='water-breathing';
update public.spell_catalog set name_ru='Хождение по воде', casting_time='Действие', spell_range='30 футов', area='До 10 добровольных существ', duration='1 час', components=array['В','С','М'], material='кусочек пробки', check_type='', damage='', effect_summary='До десяти существ могут ходить по любой жидкой поверхности — воде, кислоте, грязи, снегу, зыбучему песку или лаве — как по твёрдой земле. Это не защищает от опасности самой среды, например жара лавы.', upcast='', notes='Ритуал. Чтобы добровольно перейти с поверхности внутрь жидкости или обратно, цель тратит Бонусное действие. При падении в жидкость цель проходит сквозь поверхность вниз.', author_description='Позволяет ходить по воде, кислоте и даже лаве. Последнее звучит гораздо безопаснее, чем является на самом деле.', author_comment='Да, по лаве можно идти. Нет, это не делает лаву прохладной. Я вынужден писать это, потому что существуют приключенцы.' where slug='water-walk';
update public.spell_catalog set name_ru='Стена ветра', casting_time='Действие', spell_range='120 футов', area='Непрерывная стена до 50 футов длиной, 15 высотой и 1 фут толщиной', duration='Концентрация, до 1 минуты', components=array['В','С','М'], material='веер и перо', check_type='При появлении: спасбросок Силы', damage='4к8 дробящего; половина при успехе', effect_summary='Поднимаешь стену сильного ветра произвольной непрерывной формы по земле. При появлении существа в её области делают спасбросок. Стена удерживает туман, дым и газы; Маленькие и меньшие летающие существа/предметы не проходят. Обычные стрелы, болты и другие лёгкие снаряды по целям за стеной автоматически отклоняются и промахиваются.', upcast='', notes='Тяжёлые снаряды великанов, осадных машин и подобные не отклоняются. Газообразные существа не могут пройти через стену.', author_description='Пятьдесят футов ветра, который бьёт, сдувает дым и заставляет стрелы передумать. Следопыты, конечно, используют его практично. Друиды — чтобы доказать, что погода тоже может быть оружием.', author_comment='Если лучник за стеной продолжает стрелять, это уже не тактика. Это отрицание.' where slug='wind-wall';
